let CollectGameMap = cc.Class({
    extends: cc.Component,

    properties: {
        callBack:null,

        // _mapWheel:null,

        map_game_node:null,
        bg:null,
        btn_close:null,
        scrollView:null,
        map_flag:null,
        mapItems:[],
    },

    Init() {
        this._initView();
        this._initListener();
    },

    _initView() {
        this.map_game_node = cc.find("safe_node/map_game_node", this.node);
        // this._mapWheel = this.map_game_node.getChildByName("map_wheel_node").getComponent("NeverlandFantasy_MapWheel");
        this.bg = this.map_game_node.getChildByName("bg");
        this.btn_close = this.map_game_node.getChildByName("btn_close").getComponent(cc.Button);
        this.scrollView = this.map_game_node.getChildByName("scrollview").getComponent(cc.ScrollView);
        this.map_flag = this.scrollView.content.getChildByName("map_flag");
        this.pos_flag = this.scrollView.content.getChildByName("pos_flag");
        this.mapItems = [];
        let mapCfg =cc.vv.gameData.getGameCfg().mapCfg;
        for(let i=1; i<=100; i++) {
            let item = this.scrollView.content.getChildByName("item_" + i);
            item["id"] = i;
            if(cc.find("Map_kuang", item)){
                cc.find("Map_kuang", item).active = false;
            }
            if(cc.find("Map_Xing", item)){
                cc.find("Map_Xing", item).active = false;
            }

            cc.find("label_step", item).getComponent(cc.Label).string = i;
            if(cc.find("addfg", item)){
                cc.find("addfg", item).active = false;
                cc.find("addfg/spine", item).active = false;
            }
            this.mapItems.push(item);
        }
        this._reset();
    },

    _initListener() {
        this.btn_close.node.on("click", this._onBtnCloseHandler.bind(this), this);
    },

    /**
     * 显示关闭按钮
     * @returns {Promise<unknown>}
     * @private
     */
    _showCloseBtn() {
        return new Promise((res)=> {
            this.btn_close.node.active = true;
            this.btn_close.node.scale = 0;
            this.btn_close.interactable = true;
            // this.btn_close.node.getChildByName("spine").active = true;
            cc.tween(this.btn_close.node)
                .to(0.3, {scale:1}, {easing:"backOut"})
                .call(()=>{
                    res();
                })
                .start();
        });
    },

    async _onBtnCloseHandler() {
        this.btn_close.interactable = false;
        // this.btn_close.node.getChildByName("spine").active = false;
        cc.tween(this.btn_close.node)
            .to(0.3, {scale:0}, {easing:"backIn"})
            .call(()=>{
                this.exitMap(true);
            })
            .start();
    },

    /**
     * 退出
     */
    exitMap(isView) {
        Global.SlotsSoundMgr.playEffect("mapClose");
        if(!isView){
            cc.vv.gameData.getCollectScript().initBar(true, 0);
        }


        let svNode = this.scrollView.node;
        cc.tween(svNode)
            .to(0.3, {y:svNode.height}, {easing:"cubicOut"})
            .call(()=>{
                this._reset();
                if(isView){
                    cc.vv.gameData.GetBottomScript().ShowBtnsByState("idle");
                }
                if(this.callBack) {
                    this.callBack();
                    this.callBack = null;
                }
            })
            .start();
    },

    /**
     * 进入
     * @param isView 是否是查看
     * @param cb
     * @returns {Promise<void>}
     */
    async enterMap(isView, cb) {
        Global.SlotsSoundMgr.playEffect("mapOpen");
        this.callBack = cb;
        this.map_game_node.active = true;
        this.bg.active = true;
        let data = cc.vv.gameData.getMapInfo();
        let currIndex = data.currId;
        if(!isView && data.state > 0) {
            currIndex -= 1;
        }

        if(isView){
            if(currIndex == 100){
                currIndex = 0;
            }
        }

        this._freshMap(currIndex);

        if(currIndex > 0) {
            let item = this.mapItems[currIndex-1];
            this.scrollView.scrollToOffset(cc.v2(0, Math.abs(item.y) - this.scrollView.node.height/2));
        }else {
            this.scrollView.scrollToBottom();
        }
        await this._scrollViewShow();
        if (isView) {
            this._showCloseBtn();
        }else {
            await this._moveMapFlag(data.currId);
            let mapCfg =cc.vv.gameData.getGameCfg().mapCfg;
            let vo = mapCfg[data.currId];
            if(vo.type < 3) {
                let respData = await new Promise((res)=> {
                    cc.vv.gameData.getMapWheelScript().open((resp)=>{res(resp)});
                });
                if(respData.freeCnt) {
                    await this._addHouseFreeCnt(data.currId, );
                }
                // this._showCloseBtn();
                this.exitMap(false);
            }else {
                cc.vv.gameData.setFreeSlotsCnt(vo.slot.cnt)
                cc.vv.gameData.setFreeWildCnt(vo.slot.wilds)

                this.exitMap(false);
            }
        }
    },

    /**
     * 加房子的免费次数
     * @returns {Promise<unknown>}
     * @private
     */
    async _addHouseFreeCnt(currIndex) {
        return new Promise(async(res)=>{
            let item = this._findNextHouse(currIndex);
            if(item) {
                this.scrollView.scrollToOffset(cc.v2(0, Math.abs(item.y) - this.scrollView.node.height/2), 0.5);
                await cc.vv.gameData.awaitTime(0.5)

                Global.SlotsSoundMgr.playEffect("addSFG");
                let addfg = cc.find("addfg", item);
                addfg.active = true;
                addfg.setScale(0);
                cc.tween(addfg).to(0.5,{scale:1}).start();
                cc.find("spine",addfg).active = true;
                cc.find("spine",addfg).getComponent(sp.Skeleton).setAnimation(0,"Map_ShuZi",false);
                cc.find("spr",addfg).getComponent("ImgSwitchCmp").setIndex(cc.vv.gameData.getMapInfo().nextSpinCount-5);

                await cc.vv.gameData.awaitTime(1)
                res();

            }else {
                res();
            }
        });
    },

    /**
     * 查找下一个house节点
     * @param currIndex
     * @returns {cc.Node|null}
     * @private
     */
    _findNextHouse(currIndex) {
        let mapCfg = cc.vv.gameData.getGameCfg().mapCfg;
        for(let i=currIndex+1; i<=100; i++) {
            let vo = mapCfg[i];
            if(vo.type == 3) {
                return this.mapItems[i-1];
            }
        }
        return null;
    },

    /**
     * 移动地图标记
     * @param toIdx
     * @private
     */
    async _moveMapFlag(toIdx) {
        let vo = cc.vv.gameData.getGameCfg().mapCfg[toIdx.toString()];
        let item = this.mapItems[toIdx-1];
        // 移动
        await new Promise((res)=> {
            let pos = item.getChildByName("pos");
            cc.tween(this.map_flag)
                .to(1, {x:item.x+pos.x, y:item.y+pos.y})
                .call(()=>{
                    this.map_flag.scaleX = vo.dockerDir || -1; // 改了人物，方向改变了
                    res();
                })
                .start();
        });

        // 播放动画
        await new Promise((res)=> {
            let animationName = "";
            let spineNode,spineAnim;
            if(vo.type == 1 || vo.type == 2){
                spineNode = cc.find("Map_Xing", item);
                spineAnim = "Map_Xing";

                Global.SlotsSoundMgr.playEffect("starWin");
            } else if(vo.type == 3){
                spineNode = cc.find("Map_Kuang", item);
                spineAnim = "Map_Kuang_"+vo.slot.cnt;

                Global.SlotsSoundMgr.playEffect("mapSFWin");
            }

            spineNode.active = true;
            spineNode.getComponent(sp.Skeleton).setAnimation(0, spineAnim, false)
            spineNode.getComponent(sp.Skeleton).setCompleteListener(()=>{
                spineNode.getComponent(sp.Skeleton).setCompleteListener(null);
                spineNode.active = false;
                res();
            })
        });
    },

    _freshMap(currIndex) {
        for (let i = 1; i <= 100; i++){
            this._markItemCmp(i, i<=currIndex);
        }

        if(currIndex > 0) {
            let item = this.mapItems[currIndex-1];
            let pos = item.getChildByName("pos");
            this.map_flag.x = item.x + pos.x;
            this.map_flag.y = item.y + pos.y;
            let vo = cc.vv.gameData.getGameCfg().mapCfg[currIndex.toString()];
            this.map_flag.scaleX = vo.dockerDir || -1; // 改了人物，方向改变了
            item = this._findNextHouse(currIndex);
            if(cc.vv.gameData.getMapInfo().nextSpinCount > 5){
                cc.find("addfg", item).active = true;
                cc.find("addfg/spr", item).getComponent("ImgSwitchCmp").setIndex(cc.vv.gameData.getMapInfo().nextSpinCount-5-1);
            }


            // item.getChildByName("icon_free_cnt").getComponent("ImgSwitchCmp").setIndex(cc.vv.gameData.getMapInfo().nextSpinCount-5);
        } else {
            this.map_flag.position = this.pos_flag.position;
            this.map_flag.scaleX = 1;
        }
    },

    /**
     * 标记完成
     */
    _markItemCmp(index, bGrey) {
        let vo = cc.vv.gameData.getGameCfg().mapCfg[index.toString()];
        let item = this.mapItems[index-1];
        let color = new cc.Color().fromHEX(bGrey ? "#898989" : "#FFFFFF");
        item.color = color;
        item.children.forEach(children=>{
            children.color = color;
        })
    },

    /**
     * map显示
     * @returns {Promise<unknown>}
     * @private
     */
    _scrollViewShow() {
        return new Promise((res)=> {
            let svNode = this.scrollView.node;
            svNode.active = true;
            cc.tween(svNode)
                .to(0.5, {y:0}, {easing:"backOut"})
                .call(()=>{
                    res();
                })
                .start();
        });
    },

    /**
     * 重置
     */
    _reset() {
        this.bg.active = false;
        this.scrollView.node.active = false;
        this.scrollView.node.y = this.scrollView.node.height/2;
        this.btn_close.node.active = false;
        this.map_game_node.active = false;
    },
});
