
cc.Class({
    extends: cc.Component,

    properties: {
        _isLock:false,
    },

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    start () {

    },

    Init(){
        this._node_collect = cc.find("safe_node/slots/node_collect", this.node);

        this._mask = cc.find("mask", this._node_collect);
        this._bar = cc.find("bar", this._mask);
        this._spine_tou = cc.find("JDT_Tou", this._node_collect);
        this._spine_bidepan = cc.find("JDT_BiDePan", this._node_collect);

        this._spine_jiesuo = cc.find("JDT_JieSuo", this._node_collect);
        this._spine_shangsuo = cc.find("BetUp_ShangSuo", this._node_collect);
        this._spine_jiman = cc.find("JDT_JiMan", this._node_collect);
        this._spine_jiman.active = false;

        this._spine_qidian = cc.find("JDT_QiDian", this._node_collect);
        this._spine_zhongdian = cc.find("JDT_ZhongDian", this._node_collect);
        this._spine_qidian.getComponent(sp.Skeleton).setAnimation(0,"JDT_QiDian_Loop", true);

        this._btn_click = cc.find("btn_click", this._node_collect);
        Global.btnClickEvent(this._btn_click, this.onClickSjt, this);
        this._btn_entrance = cc.find("btn_entrance", this._node_collect);
        Global.btnClickEvent(this._btn_entrance, this.onClickEntrance, this);

        this._flyNode = cc.find("flyNode", this._node_collect);
        this._fly_xing = cc.find("fly_xing", this._flyNode);
        this._tip_xing = cc.find("tip_xing", this._flyNode);
        this._fly_xing.active = false;
        this._tip_xing.active = false;


        let progressData = cc.vv.gameData.getProgressData();
        this.initBar(true, progressData.totalCnt/progressData.needCnt);
        this.initSjtState();

        Global.registerEvent(cc.vv.gameData._EventId.SLOT_TOTALBET_UPDATED,this.onEventTotalbetUpdated,this)// 押注额改变

    },

    // 进度条长度
    initBar(init, percent){
        let pro = Math.min(percent, 1);
        let width = 530 * pro;

        if(init) {
            this._mask.width = width;
            this._spine_tou.active = percent != 0;
            this._spine_bidepan.active = percent != 0;
            this._spine_tou.position = cc.v2(this._mask.x + width, 0);
            this._spine_bidepan.position = cc.v2(this._mask.x + width - 10, -3);

            // if(this._spine_tou.active){
            //     this._spine_bidepan.getComponent(sp.Skeleton).setAnimation(0,"JDT_BiDePan_Loop1", true);
            // }
        } else {
            if(!this._spine_tou.active){
                this._spine_tou.active = true;
            }
            if(!this._spine_bidepan.active){
                this._spine_bidepan.active = true;
            }

            cc.tween(this._spine_tou).to(0.5, {position:cc.v2(this._mask.x + width, 0)}).start()
            cc.tween(this._spine_bidepan)
            //     .call(()=>{this._spine_bidepan.getComponent(sp.Skeleton).setAnimation(0,"JDT_BiDePan_End1", false);})
                .to(0.5, {position:cc.v2(this._mask.x + width-10, -3)})
            //     .call(()=>{
            //         this._spine_bidepan.getComponent(sp.Skeleton).setAnimation(0,"JDT_BiDePan_End3", false);
            //         this._spine_bidepan.getComponent(sp.Skeleton).addAnimation(0,"JDT_BiDePan_Loop1", true);})
                .start()


            cc.tween(this._mask).to(0.5, {width:width}).start()
        }
    },

    // 进度条能量收集
    async playCollectAnim(idxs){
        if(!this._isLock && idxs.length > 0){
            Global.SlotsSoundMgr.playEffect("collectStart");
            let progressData = cc.vv.gameData.getProgressData();

            for (let i = 0; i < idxs.length; i++){
                let idx = idxs[i];

                let fly_xing = cc.instantiate(this._fly_xing);
                let tip_xing = cc.instantiate(this._tip_xing);
                fly_xing.parent = this._flyNode;
                tip_xing.parent = this._flyNode;

                let symbol = cc.vv.gameData.GetSlotsScript().GetSymbolByIdx(idx);
                let startPos = this._flyNode.convertToNodeSpaceAR(symbol.node.convertToWorldSpaceAR(cc.v2(0,0)));
                let endPos = this._flyNode.convertToNodeSpaceAR(this._spine_qidian.convertToWorldSpaceAR(cc.v2(0,0)));

                tip_xing.active = true;
                tip_xing.position = startPos;
                tip_xing.getComponent(sp.Skeleton).setAnimation(0,"ShouJiXingTiShi",false);
                tip_xing.getComponent(sp.Skeleton).setCompleteListener(()=>{
                    tip_xing.destroy();
                    fly_xing.active = true;
                    fly_xing.position = startPos;
                    fly_xing.getComponent(sp.Skeleton).setAnimation(0,"NG_Xing",false);
                    cc.tween(fly_xing).to(0.5, {position:endPos}).call(()=>{fly_xing.destroy()}).start()
                })

                symbol.playCollectResult();
            }
            await cc.vv.gameData.awaitTime(0.7);
            Global.SlotsSoundMgr.playEffect("collectOver");

            await cc.vv.gameData.awaitTime(0.3);
            this._spine_qidian.getComponent(sp.Skeleton).setAnimation(0,"JDT_QiDian_Intro", false);
            this._spine_qidian.getComponent(sp.Skeleton).addAnimation(0,"JDT_QiDian_Loop", true);

            this.initBar(false, progressData.totalCnt/progressData.needCnt);
        }
    },

    // 收集条集满
    async fullSjt(){
        return new Promise(async (success)=> {
            this._spine_jiman.active = true;
            this._spine_jiman.getComponent(sp.Skeleton).setAnimation(0,"JDT_JiMan", false);

            await cc.vv.gameData.awaitTime(0.5);
            this._spine_zhongdian.getComponent(sp.Skeleton).setAnimation(0,"JDT_ZhongDian_End", false);
            this._spine_zhongdian.getComponent(sp.Skeleton).addAnimation(0,"JDT_ZhongDian_Loop", true);

            await cc.vv.gameData.awaitTime(0.8);
            success();
        })
    },

    // 初始化收集条状态
    initSjtState(){
        let curBet = cc.vv.gameData.GetBetIdx();
        let needBet = cc.vv.gameData.getNeedBet();

        this._isLock = curBet < needBet;
        if(this._isLock){
            this._spine_shangsuo.active = true;
            this._spine_shangsuo.getComponent(sp.Skeleton).setAnimation(0,"BetUp_ShangSuo_Loop_EN",true);
        } else {
            this._spine_shangsuo.active = false;
        }

        this._spine_jiesuo.active = false;
    },

    // 点击收集条
    onClickSjt(){
        if (!cc.vv.gameData.GetBottomScript().GetSpinBtnState()) return;
        if (cc.vv.gameData.GetAutoModelTime() > 0) return;
        // if (cc.vv.gameData.isFreeGame()) return;
        // if (cc.vv.gameData.isBonusGame()) return;

        let curBet = cc.vv.gameData.GetBetIdx();
        let needBet = cc.vv.gameData.getNeedBet();
        if(this._isLock && needBet >= curBet){
            cc.vv.gameData.GetBottomScript().SetBetIdx(needBet);
        }
    },

    // 押注额改变
    onEventTotalbetUpdated(){
        let curBet = cc.vv.gameData.GetBetIdx();
        let needBet = cc.vv.gameData.getNeedBet();

        let self = this;
        if(this._isLock && curBet >= needBet) { // 解锁
            Global.SlotsSoundMgr.playEffect("unlock");
            this._isLock = false;

            this._spine_shangsuo.active = false;
            this._spine_jiesuo.active = true;
            this._spine_jiesuo.getComponent(sp.Skeleton).setAnimation(0,"JDT_JieSuo",false);
            this._spine_jiesuo.getComponent(sp.Skeleton).setCompleteListener(()=>{this._spine_jiesuo.active = false;})

        } else if(!this._isLock && curBet < needBet){   // 上锁
            Global.SlotsSoundMgr.playEffect("lock");
            this._isLock = true;

            this._spine_jiesuo.active = false;
            this._spine_shangsuo.active = true;

            this._spine_shangsuo.getComponent(sp.Skeleton).setAnimation(0,"BetUp_ShangSuo_Intro_EN",false);
            this._spine_shangsuo.getComponent(sp.Skeleton).addAnimation(0,"BetUp_ShangSuo_Loop_EN",true);
        }

        // this._spine_tou.active = !this._isLock
        // this._spine_bidepan.active = !this._isLock
    },


    onClickEntrance(){
        if (!cc.vv.gameData.GetBottomScript().GetSpinBtnState()) return;
        if (cc.vv.gameData.GetAutoModelTime() > 0) return;
        // if (cc.vv.gameData.isFreeGame()) return;
        // if (cc.vv.gameData.isBonusGame()) return;

        cc.vv.gameData.GetBottomScript().ShowBtnsByState("moveing_1");
        cc.vv.gameData.getMapScript().enterMap(true);
    },

    // update (dt) {},
});
