    // 云清屏动画
    async playYunQpAnim(bRemain,bShow){
        this._qp_yun.active = true;

        let self = this;
        if(bRemain){
            if(bShow){
                Global.SlotsSoundMgr.playEffect("fgTransition");
                this._qp_yun.getComponent(sp.Skeleton).setAnimation(0,"FG_GuoChang_Intro",false);
                this._qp_yun.getComponent(sp.Skeleton).addAnimation(0,"FG_GuoChang_Loop",true);
            } else {
                Global.SlotsSoundMgr.playEffect("opencloud");
                let entry = this._qp_yun.getComponent(sp.Skeleton).setAnimation(0,"FG_GuoChang_End",false);
                this._qp_yun.getComponent(sp.Skeleton).setTrackCompleteListener(entry, ()=>{
                    self._qp_yun.active = false;
                })
            }
        } else {
            this._qp_yun.getComponent(sp.Skeleton).setAnimation(0,"FG_GuoChang_Intro",false);
            this._qp_yun.getComponent(sp.Skeleton).addAnimation(0,"FG_GuoChang_Loop",false);
            let entry = this._qp_yun.getComponent(sp.Skeleton).addAnimation(0,"FG_GuoChang_End",false);
            this._qp_yun.getComponent(sp.Skeleton).setTrackCompleteListener(entry, ()=>{
                self._qp_yun.active = false;
            })
            Global.SlotsSoundMgr.playEffect("fgTransition");
            await cc.vv.gameData.awaitTime(0.8)
            Global.SlotsSoundMgr.playEffect("opencloud");
        }

    },

    // 星星清屏动画
    playXingQpAnim(){
        Global.SlotsSoundMgr.playEffect("superFgTransition");
        let self = this;
        this._qp_character.active = true;
        this._qp_character.getComponent(sp.Skeleton).setAnimation(0,"skill",false);
        this._qp_character.getComponent(sp.Skeleton).setCompleteListener(()=>{
            self._qp_character.active = false;
        })
    },

