
cc.Class({
    extends: require("LMSlots_Slots_Base"),

    properties: {

    },


    //断线重连的显示
    //可根据自己断线逻辑重写
    async ReconnectShow(){
        this._topScript.SetBackLobby(false);
        this._bottomScript.ShowBtnsByState("moveing_1");

        let mapInfo = cc.vv.gameData.getMapInfo();
        if(mapInfo && mapInfo.state === 1){
            await this.enterCollectGame(true);

            // await this.triFreeGame();
        } else if(mapInfo && mapInfo.state === 2 && cc.vv.gameData.GetTotalFree() > 0){
            if(cc.vv.gameData.GetTotalFree()==cc.vv.gameData.GetFreeTime()) { // 触发
                await this.enterCollectGame(false);
            }
            await cc.vv.gameData.getFreeScript().initShowSlotsData(false);
        }

        let wheelGame = cc.vv.gameData.getWheelGame();
        if(wheelGame){
            if (wheelGame.state === 0 || wheelGame.state === 1){  // 转盘
                await cc.vv.gameData.getFreeWheelScript().enterFreeWheel(wheelGame.state);

                await this.triFreeGame();
            } else if (wheelGame.state === 2){  // 免费
                await cc.vv.gameData.getFreeScript().initShowSlotsData(false);
            }
        }

        this._topScript.StopMove()
        this._bottomScript.CanDoNextRound();
    },

    StartMove(){
        if(cc.vv.gameData.isFreeGame()){
            cc.vv.gameData.getFreeScript().StartMove();
        }
        else {
            this._super();
            Global.SlotsSoundMgr.playNormalBgm();
        }
    },

    StopMove(){
        if(cc.vv.gameData.isFreeGame()){
            cc.vv.gameData.getFreeScript().StopMove();
        }
        else {
            this._super();
        }
    },

    onMsgSpine(msg){
        if(cc.vv.gameData.isFreeGame()){
            cc.vv.gameData.getFreeScript().onMsgSpine(msg);
        }
        else {
            this._super(msg);
        }
    },

    //设置reel旋转的状态；
    //是否加速框；
    //是否加速旋转
    //是否停止音效；
    //是否播放背景特效
    SetReelStateInfo:function(cards){
        if (!this._cfg.reelStateInfo) {
            return;
        }
        let reelResults = []
        for(let i = 0;i < cards.length; i++){
            let id = cards[i]
            let col = i % this._col
            if(!reelResults[col]) reelResults[col] = []
            reelResults[col].push(id)
        }

        for (let info of this._cfg.reelStateInfo) {
            let stateInfo = Global.copy(info);
            stateInfo.isStop = false
            stateInfo.isAnt = false
            stateInfo.stopIdx = 0;
            let stopCnt = 0;

            let triggerCount = stateInfo.mini
            let countsConfig = Global.copy(stateInfo.counts);
            let haveCount = 0
            let isContinuous = true
            for(let i = 0; i < reelResults.length; i++){
                let item = this._reels[i]
                let reelRes = reelResults[i]
                stateInfo.isStop = false
                stateInfo.isAnt = false
                if (haveCount >= triggerCount-1 && stateInfo.counts[i] > 0 && isContinuous) {  //满足条件 需要播放加速框
                    stateInfo.isAnt = true
                }
                let reelCountOfID = reelRes.reduce((a, v) => stateInfo.id.includes(v) ? a + 1 : a + 0, 0);
                haveCount +=  reelCountOfID
                countsConfig.shift()
                let remainingCount = (countsConfig.length > 0 ? countsConfig.reduce((x,y)=>x+y):0) + haveCount
                if (reelCountOfID > 0 && remainingCount >= triggerCount && isContinuous) {  //满足条件 播放停止动画和停止音效
                    stateInfo.isStop = true
                    stateInfo.stopIdx = stopCnt;
                    stopCnt += 1;
                }
                if (stateInfo.continuous && stateInfo.counts[i] > 0 && reelCountOfID == 0) {
                    isContinuous = false
                }
                item.AddReelStateInfo(Global.copy(stateInfo))
            }
        }
    },

    OnSpinEnd(){
        if(cc.vv.gameData.isFreeGame()){
            cc.vv.gameData.getFreeScript().OnSpinEnd();
        } else {
            this.onSpinEndAction();
        }
    },

    async onSpinEndAction(){

        this.playCollectAnim();

        //显示中奖路线
        this.ShowWinTrace();
        //显示底部赢钱
        let nWin = cc.vv.gameData.GetGameWin()
        let nTotal = nWin
        if(cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetTotalFree() != cc.vv.gameData.GetFreeTime()){
            nTotal = cc.vv.gameData.getFreeWinCoin()
        }
        await new Promise((sucess, failed)=>{
            this.ShowBottomWin(nWin,nTotal,true,sucess)
        });

        // 进入地图游戏
        if (this._gameInfo.mapInfo.state == 1 || (this._gameInfo.mapInfo.state == 2 && this._gameInfo.freeCnt==this._gameInfo.allFreeCnt)) {
            if(!nWin){
                await cc.vv.gameData.awaitTime(1.5)
            }
            await this.enterCollectGame(false);

            if(this._gameInfo.mapInfo.state == 2){
                await this.triFreeGame();
            }
        }

        // 免费前的转盘游戏
        if(this._gameInfo.wheelGame && this._gameInfo.wheelGame.state == 0){
            await this.triFreeWheel();
            await this.triFreeGame();
        }

        this.CanDoNextRound();
    },

    // 进入地图游戏
    enterCollectGame(bBack) {
        return new Promise(async (success)=> {
            this._bottomScript.ShowBtnsByState("moveing_1");
            if(!bBack){
                await cc.vv.gameData.getCollectScript().fullSjt();
            }

            cc.vv.gameData.getMapScript().enterMap(false, success);
        });
    },

    // 触发免费转盘游戏
    triFreeWheel(){
        return new Promise(async (success)=> {
            let cards = this._gameInfo.resultCards;
            for (let i = 0; i < cards.length; i++){
                if(cards[i] === 2){
                    this.GetSymbolByIdx(i+1).playTriggerAnimation();
                }
            }
            Global.SlotsSoundMgr.playEffect("triggering");

            await cc.vv.gameData.awaitTime(2);

            await cc.vv.gameData.getFreeWheelScript().enterFreeWheel();
            success();
        });
    },

    // 触发免费游戏
    triFreeGame(){
        return new Promise(async (success)=> {
            if(cc.vv.gameData.getMapInfo().state == 2){
                let mapCfg =cc.vv.gameData.getGameCfg().mapCfg;
                let data = cc.vv.gameData.getMapInfo();
                let vo = mapCfg[data.currId];
                await cc.vv.gameData.getPopupScript().showTriFree(true, vo.slot.wildIdx-1);
                cc.vv.gameData.getPopupScript().playXingQpAnim();
                await cc.vv.gameData.awaitTime(2);
            } else {
                await cc.vv.gameData.getPopupScript().showTriFree(false, cc.vv.gameData.getWheelGame().wildResultId-1);
                cc.vv.gameData.getPopupScript().playYunQpAnim(true, false);
                // await cc.vv.gameData.awaitTime(0.5);
            }

            this.ShowGameview(true);

            await cc.vv.gameData.getFreeScript().initShowSlotsData(true);
            success();
        });
    },

    // 播放能量收集动画
    playCollectAnim(){
        let cards = this._gameInfo.resultCards;
        let list = [];
        for (let i = 0; i < cards.length; i++){
            if(cards[i] === 3){     // bonus图标
                list.push(i+1);
            }
        }
        if(list.length > 0){
            cc.vv.gameData.getCollectScript().playCollectAnim(list);
        }
    },

    // update (dt) {},
});
