cc.Class({
    extends: cc.Component,

    properties: {
        roundCount: 10,    // 圈数
        _canSpin:false,      // 是否可转
        _data:null,
        _callBack:null,      // 完成后回调

        switchUis:[], // 需要根据类型变换的ui
    },

    _getRotation(index) {
        let ret = -this.roundCount * 360;
        let unitAngle = 360/8;
        let indexsAngle = [
            0,
            -360+unitAngle*1,
            -360+unitAngle*2,
            -360+unitAngle*3,
            -360+unitAngle*4,
            -360+unitAngle*5,
            -360+unitAngle*6,
            -360+unitAngle*7,
        ];
        ret += indexsAngle[index];
        return ret;
    },

    onLoad() {

    },


    Init(){
        this._map_wheel_node = cc.find("safe_node/map_game_node/map_wheel_node", this.node);
        this._map_wheel_node.active = false;

        this._bg = cc.find("bg", this._map_wheel_node);
        this._wheel = cc.find("wheel", this._map_wheel_node);

        this._spine_down = cc.find("spine_down", this._wheel);
        this._spine_bg = cc.find("spine_bg", this._wheel);
        this._lbl_base_prize = cc.find("base_prize/lbl", this._wheel);
        this._base_result = cc.find("base_prize/spine_result", this._wheel);
        this._board = cc.find("board", this._wheel);
        this._spine_win = cc.find("spine_win", this._wheel);

        this._btn_spin = cc.find("btn_spin", this._wheel);
        Global.btnClickEvent(this._btn_spin, this._onStartWheelHandler, this);
        this._spine_btn = cc.find("btn_spin/spine", this._wheel);
        this._spine_kuang = cc.find("spine_kuang", this._wheel);


        this.switchUis.push(cc.find("base_prize", this._wheel));
        this.switchUis.push(cc.find("board_bg", this._wheel));
        this.switchUis.push(this._board);
        this.switchUis.push(this._btn_spin);
        this.switchUis.push(cc.find("icon_arrow", this._wheel));
    },


    async _onStartWheelHandler() {
        if(!this._canSpin) {
            return;
        }
        this._btn_spin.stopAllActions();
        this._canSpin = false
        let msg = await cc.vv.gameData.reqSubGame({rtype:1});
        if(msg.data) {
            this._data.freeCnt = msg.data.freeCnt;
            this._data.winCoin = msg.data.winCoin;
            this._data.idx = msg.data.idx;
            this._data.jackpot = msg.data.jackpot;
        }
        this._startWheel();
    },

    _reset() {
        this._board.angle = 0;
        this._bg.active = false;
        this._wheel.active = false;
        this._wheel.y = this._wheel.height/2;
        this._spine_btn.active = false;
        this._spine_win.active = false;
        this._lbl_base_prize.getComponent(cc.Label).string = "";
        this._spine_down.active = false;
        this._spine_bg.active = false;
        this._base_result.active = false;
        this._data = {
            wheel_type:0,   // 转盘类型
            freeCnt:0,      // 加次数
            winCoin:0,      // 赢金币
            jackpot:null,   // 赢奖池
            idx:0
        };
    },

    async _startWheel() {
        Global.SlotsSoundMgr.playEffect("WheelSpin");

        this._spine_btn.active = false;
        this._spine_kuang.active = false;

        cc.tween(this._board)
            .to(6, {angle:this._getRotation(this._data.idx-1)}, { easing: 'quartInOut' })
            .start();

        await cc.vv.gameData.awaitTime(6);

        this._spine_win.active = true;
        this._spine_win.getComponent(sp.Skeleton).setAnimation(0,"MapSuoDing_"+(this._data.wheel_type === 2?"J":"Y"), true);
        this._spine_bg.active = true;
        this._spine_bg.getComponent(sp.Skeleton).setAnimation(0,"MapBeiJing", true);

        await cc.vv.gameData.awaitTime(1);
        if(this._data.winCoin) {    // 赢钱
            if(this._data.jackpot){   // 中奖池
                await cc.vv.gameData.getPopupScript().showJpWin(this._data.winCoin, this._data.jackpot.id)
            } else {    // 赢倍率
                Global.SlotsSoundMgr.playEffect("trophyNumbr");
                this._base_result.active = true;
                this._base_result.getComponent(sp.Skeleton).setAnimation(0,"Map_JieSuanLiZi",false);

                Global.doRoallNumEff(this._lbl_base_prize,0,this._data.winCoin, 5,null,null,0,true);
                await cc.vv.gameData.awaitTime(5);
                await cc.vv.gameData.getPopupScript().showWinMapWheel(this._data.winCoin)
            }

            cc.vv.gameData.AddCoin(this._data.winCoin);
            cc.vv.gameData.GetTopScript().ShowCoin();
        } else {    // free次数

        }

        await this.close();
        if(this._callBack) {
            this._callBack({freeCnt:this._data.freeCnt, winCoin:this._data.winCoin});
        }
    },

    _fresh() {
        let vo = cc.vv.gameData.getGameCfg().mapCfg[cc.vv.gameData.getMapInfo().currId.toString()];
        this._data.wheel_type = vo.type;
        this.switchUis.forEach(element => {
            element.getComponent("ImgSwitchCmp").setIndex(this._data.wheel_type-1);
        });

        this._lbl_base_prize.getComponent(cc.Label).string = Global.FormatNumToComma(cc.vv.gameData.getMapInfo().startPrice);
    },

    /**
     * 开始 开始转盘流程
     */
    open(cb) {
        this._callBack = cb;
        this._map_wheel_node.active = true;
        this._reset();
        this._canSpin = true;
        this._fresh();

        // 显示背景
        this._bg.active = true;
        this._bg.opacity = 1;
        this._bg.runAction(cc.fadeTo(1, 200));

        // 显示盘
        this._wheel.active = true;

        Global.SlotsSoundMgr.playEffect("smallWheelShow");
        this._spine_down.active = true;
        this._spine_down.getComponent(sp.Skeleton).setAnimation(0, "Map_XiaLuo", true)
        cc.tween(this._wheel)
            .to(0.5, {y:0})
            .call(()=>{
                this._spine_down.active = false;
            })
            .start();
        this._spine_btn.active = true;
        this._spine_btn.getComponent(sp.Skeleton).setAnimation(0, "Spin_Loop_S_"+(this._data.wheel_type === 2?"J":"Y"), true);

        this._spine_kuang.active = true;
        this._spine_kuang.getComponent(sp.Skeleton).setAnimation(0, "Spin_Loop_G_"+(this._data.wheel_type === 2?"J":"Y"), true);
        cc.vv.gameData.checkAutoPlay(this._btn_spin, this._onStartWheelHandler.bind(this));

    },

    async close() {
        return new Promise((res) => {
            // 隐藏背景
            cc.tween(this._bg)
                .to(0.5, {opacity:0})
                .call(()=>{
                    this._bg.active = false;
                })
                .start();

            // 隐藏转盘
            cc.tween(this._wheel)
                .to(0.5, {y:this._wheel.height/2}, {easing:"backIn"})
                .call(()=>{
                    this._wheel.active = false;
                    this._map_wheel_node.active = false;
                    Global.SlotsSoundMgr.playUnLoopBgm('bg_bgm');
                    res();
                })
                .start();
        });
    },
});
