    Init(){
        this._free_wheel = cc.find("safe_node/free_wheel", this.node)
        this._free_wheel.active = false;

        this._spr_mask = cc.find("spr_mask", this._free_wheel);
        this._node_count = cc.find("count", this._free_wheel);
        this._node_wheel = cc.find("wheel", this._free_wheel);

        this._lbl_cnt = cc.find("count/lbl_cnt", this._free_wheel);
        this._spine_cnt = cc.find("count/spine", this._free_wheel);

        this._wheel_out = cc.find("wheel/wheel_out", this._free_wheel);
        this._wheel_in = cc.find("wheel/wheel_in", this._free_wheel);
        this._item5 = cc.find("item5", this._wheel_in);

        this._spine_win = cc.find("wheel/spine_win", this._free_wheel);

        this._btn_spin = cc.find("wheel/spin", this._free_wheel);
        Global.btnClickEvent(this._btn_spin, this.clickSpinBtn, this);
        this._spine_btn = cc.find("spine", this._btn_spin);

        this._win_extra = cc.find("win_extra", this._free_wheel);
    },

    enterFreeWheel(){
        return new Promise(async (success, failed)=> {
            cc.vv.gameData.getPopupScript().playYunQpAnim(true,true);
            await cc.vv.gameData.awaitTime(1);
            Global.SlotsSoundMgr.playBgm("wheelbgm");

            this._wheelGame = cc.vv.gameData.getWheelGame();

            this.initWheelNode();

            await this.playShowWheel();
            this._canSpin = true;
            cc.vv.gameData.checkAutoPlay(this._btn_spin, this.clickSpinBtn.bind(this));

            this._freeSucc = success;
        })
    },

    initWheelNode(){
        if(this._wheelGame.state == 1){
            this._wheel_out.angle = (this._wheelGame.wildResultId-1)*(360/8)+180;
            this._item5.getComponent("ImgSwitchCmp").setIndex(this._wheelGame.slotItems[4].slotCnt-2);
        } else {
            this._wheel_out.angle = 0;
            this._item5.getComponent("ImgSwitchCmp").setIndex(3);
        }
        this._lbl_cnt.getComponent(cc.Label).string = this._wheelGame.totalFreeCnt;
        this._wheel_in.angle = 0;

        this._spine_btn.getComponent(sp.Skeleton).setAnimation(0,"Spin_Loop_S",true);

        this._spine_cnt.active = false;
        this._spine_win.active = false;
        this._win_extra.active = false;
    },

    playShowWheel(){
        return new Promise(async (success, failed)=> {
            Global.SlotsSoundMgr.playEffect("wheelShow");
            this._free_wheel.active = true;
            this._spr_mask.opacity = 0;
            this._node_count.setScale(0);
            this._node_wheel.setScale(0);

            cc.tween(this._spr_mask).to(0.5, {opacity: 150}).start();
            cc.tween(this._node_count).to(0.5, {scale: 1}, {easing: "backOut"}).start()
            cc.tween(this._node_wheel).to(0.5, {scale: 1}, {easing: "backOut"}).start()

            await cc.vv.gameData.awaitTime(0.5)

            success();
        });
    },

    playHideWheel(){
        return new Promise(async (success, failed)=> {

            cc.tween(this._node_count).to(0.5, {opacity: 0}).start();
            cc.tween(this._node_wheel).to(0.5, {opacity: 0}).start();

            await cc.vv.gameData.awaitTime(0.5);
            this._free_wheel.active = false;
            this._node_count.opacity = 255;
            this._node_wheel.opacity = 255;

            /*this._wheel_out.angle = 0;
            this._wheel_in.angle = 0;

            this._spine_win.active = false;*/

            success();
        });
    },

    async clickSpinBtn(){
        if(!this._canSpin){
            return
        }
        this._canSpin = false;
        this._btn_spin.stopAllActions();
        this._spine_btn.getComponent(sp.Skeleton).setAnimation(0,"Spin_Intro",false);

        let state = this._wheelGame.state
        let msg = await cc.vv.gameData.reqSubGame({rtype:2});
        if(msg.code == 200){
            this._wheelGame = msg.data.wheelGame;

            await this.startWheel(state);
            Global.SlotsSoundMgr.playEffect("wheelWin");
            this._spine_win.active = true;
            this._spine_win.getComponent(sp.Skeleton).setAnimation(0,"FGSuoDing", false);
            this._spine_win.getComponent(sp.Skeleton).setCompleteListener(()=>{
                this._spine_win.active = false;
            })
            this._spine_btn.getComponent(sp.Skeleton).setAnimation(0,"Spin_End",false);
            await cc.vv.gameData.awaitTime(1);

            if(this._wheelGame.state === 1){
                await this.winExtraSpins();

                this._spine_btn.getComponent(sp.Skeleton).addAnimation(0,"Spin_Loop_S",true);
                this._canSpin = true;
                cc.vv.gameData.checkAutoPlay(this._btn_spin, this.clickSpinBtn.bind(this));
            } else {
                cc.vv.gameData.setFreeWildCnt(this._wheelGame.wildCols);
                cc.vv.gameData.setFreeSlotsCnt(this._wheelGame.slotCnt);
                cc.vv.gameData.SetTotalFree(this._wheelGame.totalFreeCnt);
                cc.vv.gameData.SetFreeTime(this._wheelGame.totalFreeCnt);

                await this.playHideWheel();
                Global.SlotsSoundMgr.stopBgm();
                if(this._freeSucc){
                    this._freeSucc();
                    this._freeSucc = null;
                }
            }
        }

    },


