    startWheel(state){
        return new Promise(async (success, failed)=> {
            Global.SlotsSoundMgr.playEffect("WheelSpin");

            let slotResultId = this._wheelGame.slotResultId[state];
            let wildResultId = this._wheelGame.wildResultId;

            let nCir = 4; //圈数
            let angle_in = (8-(slotResultId-1))*(360/8) - this._wheel_in.angle + nCir*360+180;
            let angle_out = (wildResultId-1)*(360/8) - this._wheel_out.angle + nCir*360+180;

            cc.tween(this._wheel_in)
                .to(6, {angle:angle_in},{ easing: 'quartInOut' })
                .start()

            if(state == 0){
                cc.tween(this._wheel_out)
                    .to(6, {angle:-angle_out},{ easing: 'quartInOut' })
                    .start()
            }

            await cc.vv.gameData.awaitTime(6)

            success();
        })
    },

    winExtraSpins(){
        return new Promise(async (success, failed)=> {
            this._win_extra.active = true;
            let spr = cc.find("spr",this._win_extra);
            let par = cc.find("par",this._win_extra);

            let sPos = this._win_extra.convertToNodeSpaceAR(this._item5.convertToWorldSpaceAR(cc.v2(0,0)));
            let ePos = this._win_extra.convertToNodeSpaceAR(this._lbl_cnt.convertToWorldSpaceAR(cc.v2(0,0)));
            spr.position = sPos;
            par.position = sPos;

            par.getComponent(cc.ParticleSystem).resetSystem();
            cc.tween(spr).to(0.5,{position:ePos}).start()
            cc.tween(par).to(0.5,{position:ePos}).start()
            Global.SlotsSoundMgr.playEffect("spinFly");

            this._item5.getComponent("ImgSwitchCmp").setIndex(this._wheelGame.slotItems[4].slotCnt-2);

            await cc.vv.gameData.awaitTime(0.5);
            this._win_extra.active = false;

            Global.SlotsSoundMgr.playEffect("fgSpinAdd");

            this._spine_cnt.active = true;
            this._spine_cnt.getComponent(sp.Skeleton).setAnimation(0,"FG_ShouJiLian",false);
            this._spine_cnt.getComponent(sp.Skeleton).setCompleteListener(()=>{
                this._spine_cnt.getComponent(sp.Skeleton).setCompleteListener();
                this._spine_cnt.active = false;
            })
            this._lbl_cnt.getComponent(cc.Label).string = this._wheelGame.totalFreeCnt;

            success();
        })
    },

